    public Role testUpdate() throws Throwable {
    LOGGER.info( "RoleTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a Role." );

    StringBuilder msg = new StringBuilder( "Failed to update a Role : " );
    Role entity = null;

    try {
        UpdateRoleCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setRoleId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created Role." );

        entity = service.updateRole( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved Role - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

