    /**
     * Tests getting all Roles.
     *
     * @return    Collection
     */
    public List<Role> testGetAll() throws Throwable {
    LOGGER.info( "RoleTest:testGetAll() - Retrieving Collection of Roles:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Role : " );
    List<Role> collection  = null;

    try {
        // call the static get method on the RoleService
        collection = service.getAllRole();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Role currEntity  = null;
            Iterator<Role> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getRoleId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

